import os,sys,json,copy,dataclasses,time
from pathlib import Path
import numpy as np,torch
from tensoraerospace.agent.im_gdhp import IMGDHPAgent
from tensoraerospace.benchmark import ControlBenchmark
from scripts.validate_ihdp_imgdhp import run_episode

torch.set_num_threads(1)
a=json.loads(Path(sys.argv[1]).read_text());out=Path(a['output']);s=180/np.pi
base=json.loads(Path(a.get('base','/tmp/imgdhp-bias-01-q5.json')).read_text())
agent=IMGDHPAgent.from_pretrained(base['checkpoint'],load_gradients=True)
for key,val in a.get('config',{}).items():setattr(agent.cfg,key,val)
for name in ('actor','critic'):
 lr=a[name+'_lr'];getattr(agent,name+'_opt').param_groups[0]['lr']=lr
 setattr(agent.cfg,name+'_lr',lr);setattr(agent.cfg,name+'_lr_min',lr);setattr(agent.cfg,name+'_lr_decay',1.)
if 'q_cost' in a:agent.cfg.track_Q=(200/s**2,a['q_cost']/s**2)
agent._R=np.asarray(agent.cfg.control_R or [0.])
def ref(n,amplitude=1):return np.vstack((np.deg2rad(np.where(np.arange(n)*.01>=2,amplitude,0)),np.zeros(n)))
def evaluate(n=2000,amplitude=1):
 m,y,u=run_episode(copy.deepcopy(agent),ref(n,amplitude),learning=True)
 b=ControlBenchmark().benchmarking_step_response(ref(n,amplitude)[0,1:],y[:,0],0,.01)
 tail=np.rad2deg(y[-max(1,int(.1*len(y))):,0]);err=amplitude-float(np.mean(tail))
 return {**m,'cpi':b['performance_index'],'static_error_deg':err,'settling_s':b['command_settling_time'],'overshoot_percent':b['command_overshoot'],'tail_peak_to_peak_deg':float(np.ptp(tail))},y,u
record={'arguments':a,'config':dataclasses.asdict(agent.cfg),'training':[],'evaluation':[]}
try:
 for ep in range(a.get('episodes',10)):
  m,_,_=run_episode(agent,ref(a.get('train_samples',1600)),learning=True,noise=a.get('noise',.02));record['training'].append(m)
  if ep in (0,4) or ep+1==a.get('episodes',10):
   m,_,_=evaluate();record['evaluation'].append({'episode':ep+1,**m});print(record['evaluation'][-1],flush=True)
 record['final'],y,u=evaluate();record['long'],yl,ul=evaluate(6000)
 record['checkpoint']=agent.save(str(out.with_suffix(''))+'-checkpoint',save_gradients=True)
 np.savez_compressed(out.with_suffix('.npz'),y=y,u=u,yl=yl,ul=ul)
except (ValueError,RuntimeError,FloatingPointError) as e:record['failure']=str(e)
out.write_text(json.dumps(record,indent=2,allow_nan=False)+'\n');print({k:v for k,v in record.items() if k in ('final','long','failure')},flush=True)

