import os
os.environ['OMP_NUM_THREADS']='1';os.environ['OPENBLAS_NUM_THREADS']='1';os.environ['MKL_NUM_THREADS']='1'
import argparse,copy,json
from pathlib import Path
import numpy as np,torch,nbformat
import matplotlib;matplotlib.use('Agg')
p=argparse.ArgumentParser();p.add_argument('--name',required=True);p.add_argument('--seed',type=int,default=0);p.add_argument('--kp',type=float,default=.2);p.add_argument('--ki',type=float,default=.02);p.add_argument('--bias',type=float,default=30);p.add_argument('--long',action='store_true');a=p.parse_args()
n=nbformat.read('example/reinforcement_learning/incremental_adp/example_im_gdhp_nonlinear_f16.ipynb',4);s={}
for i in (1,3,5,7):exec(n.cells[i].source,s)
from tensoraerospace.agent.im_gdhp import IMGDHPAgent
from tensoraerospace.benchmark import ControlBenchmark
path='/tmp/imgdhp-parameter-search/'+('alpha-refine-04' if a.seed==0 else f'alpha-seeds-0{a.seed}')+'.json'
rec=json.loads(Path(path).read_text())
if rec.get('checkpoint'):agent=IMGDHPAgent.from_pretrained(rec['checkpoint'],load_gradients=True)
else:
 from dataclasses import replace
 agent=IMGDHPAgent(2,1,1,[0],replace(s['cfg'],seed=a.seed))
 for ep in range(30):
  s['run_episode'](agent,s['REFERENCE'],learning=True,noise=.1)
  if (ep+1)%10==0:print('TRAIN',ep+1,flush=True)
 agent.save('/tmp/imgdhp-offset/seed2-original',save_gradients=True)
agent.reset();agent.cfg.identifier_mode='output'
x=torch.zeros(1);jac=torch.autograd.functional.jacobian(agent.actor,x).item()*np.pi/180
agent.retune_actor_inputs(feedback_gain=a.kp/jac,bias_input=a.bias)
u=agent.actor(x);grads=torch.autograd.grad(u.sum(),tuple(agent.actor.parameters()));norm=sum(float((g*g).sum()) for g in grads)
lam=agent.critic(x)[1].item();b=agent.incremental_model.B[0,0]
rate=a.ki*.01*(180/np.pi)/(lam*lam*abs(b)*norm)
agent.actor_opt.param_groups[0]['lr']=agent.cfg.actor_lr=rate;agent.cfg.actor_lr_decay=1.
print('CONFIG',jac,a.kp/jac,lam,b,norm,rate,flush=True)
r={'seed':a.seed,'target_kp':a.kp,'target_ki':a.ki,'bias_input':a.bias,'feedback_gain':a.kp/jac,'actor_lr':rate,'lambda':lam,'B0':b,'jacobian_norm2':norm,'evaluations':[]}
try:
 s['run_episode'](agent,np.zeros((1,6000)),learning=True)
 r['checkpoint']=agent.save('/tmp/imgdhp-offset/'+a.name+'-checkpoint',save_gradients=True)
 for amp in (1.,-1.,.5,2.):
  ref=s['step_reference'](6000,amp);m,y,u=s['run_episode'](copy.deepcopy(agent),ref,learning=True)
  row={'amplitude':amp,'pre_peak':float(np.rad2deg(abs(y[:1999,0])).max())}
  for samples in (3800,6000):
   yy=y[:samples-1];rr=ref[:,:samples];error=np.rad2deg(rr[0,1:]-yy[:,0]);tail=int(.1*len(yy))
   met=ControlBenchmark().benchmarking_step_response(rr[0,1:],yy[:,0],0.,.01)
   row[str(samples)]={'tail':float(error[-tail:].mean()),'tail_ptp':float(np.ptp(error[-tail:])),**met}
  r['evaluations'].append(row);print('EVAL',row,flush=True)
  np.savez_compressed('/tmp/imgdhp-offset/'+a.name+f'-{amp}.npz',y=y,u=u,ref=ref)
except (ValueError,RuntimeError,FloatingPointError) as e:r['failure']=str(e);print('FAIL',str(e),flush=True)
Path('/tmp/imgdhp-offset/'+a.name+'.json').write_text(json.dumps(r,indent=2))

