import os
os.environ['OMP_NUM_THREADS']='1';os.environ['OPENBLAS_NUM_THREADS']='1';os.environ['MKL_NUM_THREADS']='1'
import argparse,json,copy
from pathlib import Path
import numpy as np,nbformat
import matplotlib;matplotlib.use('Agg')
p=argparse.ArgumentParser();p.add_argument('--kind',choices=['steps','sequence','long'],required=True);a=p.parse_args()
n=nbformat.read('example/reinforcement_learning/incremental_adp/example_im_gdhp_nonlinear_f16.ipynb',4);s={}
for i in (1,3,7):exec(n.cells[i].source,s)
from tensoraerospace.agent.im_gdhp import IMGDHPAgent
from tensoraerospace.benchmark import ControlBenchmark
r=json.loads(Path('/tmp/imgdhp-offset/norm-s0-k25.json').read_text());agent=IMGDHPAgent.from_pretrained(r['checkpoint'],load_gradients=True)
cases=[]
if a.kind=='steps':
 for amp in (-2.,-.75,.75,1.5,2.5):cases.append((f'heldout-{amp}',s['step_reference'](6000,amp),[(20.,amp)]))
elif a.kind=='sequence':
 levels=[(0.,0.),(20.,1.),(60.,0.),(100.,-1.),(140.,.5),(180.,-2.),(220.,0.)]
 ref=np.zeros((1,26000))
 for t,amp in levels:ref[:,round(t/.01):]=np.deg2rad(amp)
 cases.append(('sequence',ref,levels))
 ref=np.zeros((1,24000));ref[:,20000:]=np.deg2rad(1.)
 cases.append(('late-step-200s',ref,[(0.,0.),(200.,1.)]))
else:cases.append(('long-500s',s['step_reference'](50000,1.),[(0.,0.),(20.,1.)]))
results=[]
for name,ref,levels in cases:
 record={'name':name}
 try:
  m,y,u=s['run_episode'](copy.deepcopy(agent),ref,learning=True)
  err=np.rad2deg(ref[0,1:]-y[:,0]);record.update(m)
  record['stages']=[]
  for (start,level),end in zip(levels,[t for t,v in levels[1:]]+[ref.shape[1]*.01]):
   tail=err[max(round((end-5)/.01),round(start/.01)):round(end/.01)-1]
   record['stages'].append({'start':start,'end':end,'reference':level,'tail_error_deg':float(tail.mean()),'tail_max_error_deg':float(abs(tail).max()),'tail_ptp_deg':float(np.ptp(tail))})
  if a.kind!='sequence':record['benchmark']=ControlBenchmark().benchmarking_step_response(ref[0,1:],y[:,0],0,.01)
  np.savez_compressed('/tmp/imgdhp-offset/'+name+'.npz',ref=ref,y=y,u=u)
 except (ValueError,RuntimeError,FloatingPointError) as e:record['failure']=str(e)
 results.append(record);print(record,flush=True)
 Path('/tmp/imgdhp-offset/validation-'+a.kind+'.json').write_text(json.dumps(results,indent=2))

